?><section class="admin-page-head"><div><span class="kicker">ADMIN / FOOD</span><h1>Food Listings</h1><p>Review every food listing and its availability.</p></div><a class="btn primary" href="index.php#admin-upload">+ Add Food</a></section><div class="admin-table-card"><div class="table-wrap"><table><thead><tr><th>Food</th><th>Donor</th><th>Quantity</th><th>Location</th><th>Expiry</th><th>Status</th><th>Update</th></tr></thead><tbody><?php foreach($foods as $f):?><tr><td><div class="table-food"><img src="<?=e(image_url($f['image'],'../'))?>"><span><b><?=e($f['title'])?></b><small><?=e($f['category'])?></small></span></div></td><td><?=e($f['donor'])?></td><td><?=intval($f['quantity'])?> <?=e($f['unit'])?></td><td><?=e($f['location'])?></td><td><?=e(date('d M Y',strtotime($f['expiry_date'])))?></td><td><span class="badge <?=badge_class($f['status'])?>"><?=e($f['status'])?></span></td><td><form class="inline-form" method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$f['id']?>"><select name="status"><option>available</option><option>completed</option><option>expired</option></select><button class="mini-btn">Update</button></form></td></tr><?php endforeach;?></tbody></table></div></div><?php require 'footer.php'; ?>
